#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_evoType;
uniform float amzp_spreadType;
uniform float amzp_shape;
uniform float amzp_colorMode;
uniform float amzp_beatSrc;
uniform float amzp_revEvo;
uniform float amzp_autop;
uniform float amzp_autoSpeed;
uniform float amzp_progress;
uniform float amzp_count;
uniform float amzp_size;
layout(color) uniform half4 amzp_colA;
layout(color) uniform half4 amzp_colB;
uniform float amzp_hueSpeed;
layout(color) uniform half4 amzp_bgCol;
uniform float amzp_scale;
uniform float amzp_angle;
uniform float2 amzp_position;
uniform float2 amzp_stretch;
uniform float amzp_alpha;
uniform float amzp_blendMode;
uniform float amzp_alphaComp;
uniform float amzp_audioLevel;
uniform float amzp_bass;
uniform float amzp_mid;
uniform float amzp_high;
uniform float amzp_audio_level;
uniform float amzp_threshold;
uniform float amzp_curve;
uniform float amzp_beatRush;
uniform float amzp_sizePunch;
uniform float amzp_pushDist;
uniform float amzp_glowPunch;
uniform float amzp_brightPunch;
uniform float amzp_life;
uniform float amzp_lifeVar;
uniform float amzp_speed;
uniform float amzp_speedVar;
uniform float amzp_sizeVar;
uniform float amzp_shrink;
uniform float amzp_fadeIn;
uniform float amzp_fadeOut;
uniform float amzp_spin;
uniform float amzp_seed;
uniform float amzp_spreadW;
uniform float amzp_spreadH;
uniform float amzp_ringR;
uniform float amzp_emitDir;
uniform float amzp_coneAngle;
uniform float amzp_gravity;
uniform float amzp_wind;
uniform float amzp_turb;
uniform float amzp_turbFreq;
uniform float amzp_glow;
uniform float amzp_brightness;
uniform float amzp_overdrawOn;
    float2 nmRot(float2 q, float a) { float c = cos(a), s = sin(a); return float2(c * q.x - s * q.y, s * q.x + c * q.y); }
    float2 nmStd(float2 p, float pxs) {
        float z = max(amzp_scale * 2.0, 0.002);
        p -= amzp_position * pxs;
        p = nmRot(p, -radians(amzp_angle));
        return p / (z * max(amzp_stretch, float2(0.01)));
    }
    float4 nmBlend(float4 tex, float4 fx) {
        float4 f = clamp(fx, 0.0, 1.0) * clamp(amzp_alpha, 0.0, 1.0);
        float4 b = tex * clamp(amzp_alphaComp, 0.0, 1.0);
        float4 o;
        if (int(amzp_blendMode) == 0) o = f;
        else if (int(amzp_blendMode) == 1) o = float4(b.rgb * (f.rgb + (1.0 - f.a)), b.a);
        else if (int(amzp_blendMode) == 2) o = float4(b.rgb + f.rgb - b.rgb * f.rgb, b.a + f.a - b.a * f.a);
        else if (int(amzp_blendMode) == 4) o = float4(b.rgb + f.rgb, max(b.a, f.a));
        else o = f + b * (1.0 - f.a);
        o = clamp(o, 0.0, 1.0);
        return float4(min(o.rgb, float3(o.a)), o.a);
    }
    float h1(float a, float b) { return fract(sin(a * 127.1 + b * 311.7 + amzp_seed * 7.31) * 43758.5453); }
    float3 hue2rgb(float h) { return clamp(abs(mod(h * 6.0 + float3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0); }
    float sdStar(float2 p, float r) {
        float a = atan(p.y, p.x);
        float rr = r * (0.42 + 0.58 * pow(abs(cos(2.5 * a)), 5.0));
        return (length(p) - rr) * 0.75;
    }
    void amzRender() {
        float4 lay = amzTexture(0, amzScreenNorm());
        float2 L = layer;
        float2 p = (amzLayerNorm() - 0.5) * L;
        p = nmStd(float2(p.x, -p.y), 1.0);
        p.y = -p.y;
        float lv = int(amzp_beatSrc) == 1 ? amzp_bass : (int(amzp_beatSrc) == 2 ? amzp_mid : (int(amzp_beatSrc) == 3 ? amzp_high : amzp_audioLevel));
        float th = clamp(amzp_threshold, 0.0, 0.95);
        float drive = pow(clamp((lv - th) / (1.0 - th), 0.0, 1.0), max(amzp_curve, 0.05));
        float T = amzp_progress * 10.0 + ((amzp_autop>0.5) ? time * amzp_autoSpeed : 0.0) + amzp_audio_level * amzp_beatRush;
        float px = 1.0;
        float N = max(floor(amzp_count + 0.5), 1.0);
        float brightF = 1.0 + amzp_brightPunch * drive;
        float sizeF = 1.0 + amzp_sizePunch * drive;
        float pushF = amzp_pushDist * drive;
        float glowF = amzp_glow * (1.0 + amzp_glowPunch * drive);
        float dirA = radians(amzp_emitDir);
        float4 acc = float4(0.0);
        for (int ii = 0; ii < 300; ii++) {
            float i = float(ii);
            if (i >= N) break;
            float lf = max(amzp_life, 0.05) * (1.0 + (h1(i, 1.0) - 0.5) * amzp_lifeVar);
            float tt = T + h1(i, 2.0) * lf;
            float cyc = floor(tt / lf);
            float age = tt - cyc * lf;
            if ((amzp_revEvo>0.5)) age = lf - age;
            float u = age / lf;
            float k = i * 13.0 + cyc * 7.77;
            float r1 = h1(k, 3.0), r2 = h1(k, 4.0), r3 = h1(i, 5.0), r4 = h1(i, 6.0);
            float spd = amzp_speed * (1.0 + (h1(k, 7.0) - 0.5) * 2.0 * amzp_speedVar);
            float2 s = float2(0.0);
            float2 radial = float2(cos(r1 * 6.2831853), sin(r1 * 6.2831853));
            if (int(amzp_spreadType) == 1) s = nmRot(float2((r1 - 0.5) * amzp_spreadW * L.x, 0.0), dirA - 1.5707963);
            else if (int(amzp_spreadType) == 2) s = radial * amzp_ringR * min(L.x, L.y);
            else if (int(amzp_spreadType) == 3) s = radial * sqrt(r2) * amzp_ringR * min(L.x, L.y);
            else if (int(amzp_spreadType) == 4) s = float2((r1 - 0.5) * amzp_spreadW * L.x, (r2 - 0.5) * amzp_spreadH * L.y);
            else if (int(amzp_spreadType) == 5) s = float2((r1 - 0.5) * L.x, (r2 - 0.5) * L.y);
            float ca = dirA + (h1(k, 8.0) - 0.5) * radians(amzp_coneAngle);
            float2 cone = float2(cos(ca), sin(ca));
            float2 wob = float2(sin(age * amzp_turbFreq * 2.1 + r3 * 6.2831853), cos(age * amzp_turbFreq * 1.7 + r4 * 6.2831853)) * amzp_turb;
            float2 q;
            float tw = 1.0;
            if (int(amzp_evoType) <= 1) {
                float2 gd = int(amzp_evoType) == 1 ? float2(0.0, -1.0) : -float2(cos(dirA), sin(dirA));
                float2 gn = float2(-gd.y, gd.x);
                float2 st = s - gd * spd * lf * 0.5 * step(4.5, float(int(amzp_spreadType)));
                q = st + gd * spd * age + gn * wob.x;
            }
            else if (int(amzp_evoType) == 2) {
                float2 dv = length(s) > 1.0 ? normalize(s) : (amzp_coneAngle >= 359.0 ? radial : cone);
                q = s + dv * spd * lf * (1.0 - exp(-3.0 * u)) / 3.0 + wob * u;
            } else if (int(amzp_evoType) == 3) q = s + cone * spd * age - float2(0.0, 0.5 * (abs(amzp_gravity) + spd * 1.5) * age * age) + wob * u;
            else if (int(amzp_evoType) == 4) {
                float rad = max(length(s), amzp_ringR * min(L.x, L.y) * (0.3 + 0.7 * r2));
                float a0 = atan(s.y, s.x + 1e-5) + spd / max(rad, 1.0) * age;
                q = float2(cos(a0), sin(a0)) * rad + wob * 0.3;
            } else if (int(amzp_evoType) == 5) {
                float rad = max(length(s), amzp_ringR * min(L.x, L.y)) * (1.0 - u);
                float a0 = atan(s.y, s.x + 1e-5) + spd / max(rad + 20.0, 1.0) * age;
                q = float2(cos(a0), sin(a0)) * rad;
            } else if (int(amzp_evoType) == 8) {
                float z = 1.0 - u;
                float persp = 0.35 / (z + 0.12);
                float r0 = amzp_ringR * min(L.x, L.y) * (0.45 + 0.55 * r2);
                float2 lane = int(amzp_spreadType) == 0 ? float2(cos(r1 * 6.2831853), sin(r1 * 6.2831853)) * r0 * 2.5
                          : (int(amzp_spreadType) == 2 || int(amzp_spreadType) == 3 ? s * 2.5 : s);
                q = lane * persp + wob * 0.2 * persp;
                tw = persp;
            } else if (int(amzp_evoType) == 6) q = s + wob * 2.0 + float2(sin(age * 0.7 + r3 * 9.0), cos(age * 0.5 + r4 * 9.0)) * spd * 0.3;
            else { q = s + wob * 0.2; tw = 0.5 + 0.5 * sin(age * (2.0 + r3 * 4.0) * amzp_turbFreq + r4 * 6.2831853); }
            if (int(amzp_evoType) <= 2 || int(amzp_evoType) == 6) q += float2(amzp_wind * age, -0.5 * amzp_gravity * age * age);
            else if (int(amzp_evoType) == 3) q += float2(amzp_wind * age, 0.0);
            if (pushF > 0.0 && length(q) > 0.5) q += normalize(q) * pushF;
            float sz = amzp_size * (1.0 + (r3 - 0.5) * 2.0 * amzp_sizeVar) * sizeF * mix(1.0, 1.0 - u, amzp_shrink);
            if (int(amzp_evoType) == 8) { float nz = u; sz *= 0.45 + 0.9 * nz; tw = smoothstep(0.05, 0.45, nz) * (1.0 - smoothstep(0.9, 1.0, nz)); }
            sz = max(sz, 0.3);
            float fa = smoothstep(0.0, max(amzp_fadeIn, 0.001), u) * (1.0 - smoothstep(1.0 - max(amzp_fadeOut, 0.001), 1.0, u)) * tw;
            float2 d = p - q;
            if (abs(d.x) > sz * 6.0 + 4.0 || abs(d.y) > sz * 6.0 + 4.0) continue;
            float2 dr = nmRot(d, -radians(amzp_spin) * age - r4 * 6.2831853);
            float sd;
            if (int(amzp_shape) == 2) { float2 b = abs(dr) - float2(sz * 0.8); sd = length(max(b, 0.0)) + min(max(b.x, b.y), 0.0); }
            else if (int(amzp_shape) == 3) sd = sdStar(dr, sz * 1.2);
            else if (int(amzp_shape) == 4) sd = abs(length(d) - sz * 0.8) - sz * 0.18;
            else if (int(amzp_shape) == 5) {
                float sa = int(amzp_evoType) == 2 ? atan(q.y - s.y, q.x - s.x + 1e-5) : (int(amzp_evoType) == 1 ? -1.5707963 : (int(amzp_evoType) == 0 ? dirA + 3.14159265 : (int(amzp_evoType) == 8 ? atan(q.y, q.x + 1e-5) : ca)));
                float2 ds = nmRot(d, -sa);
                ds.x = max(abs(ds.x) - sz * 2.0, 0.0);
                sd = length(ds) - sz * 0.25;
            } else if (int(amzp_shape) == 7) {
                float2 hp = dr / (sz * 1.7) + float2(0.0, 0.5);
                hp.x = abs(hp.x);
                float hd;
                if (hp.y + hp.x > 1.0) hd = length(hp - float2(0.25, 0.75)) - 0.35355339;
                else hd = sqrt(min(dot(hp - float2(0.0, 1.0), hp - float2(0.0, 1.0)), dot(hp - 0.5 * max(hp.x + hp.y, 0.0), hp - 0.5 * max(hp.x + hp.y, 0.0)))) * sign(hp.x - hp.y);
                sd = hd * sz * 1.7;
            } else if (int(amzp_shape) == 8) sd = (abs(dr.x) + abs(dr.y) * 0.7 - sz) * 0.7;
            else if (int(amzp_shape) == 9) {
                float2 tp = dr / sz;
                const float k3 = 1.7320508;
                tp.x = abs(tp.x) - 1.0; tp.y = tp.y + 1.0 / k3;
                if (tp.x + k3 * tp.y > 0.0) tp = float2(tp.x - k3 * tp.y, -k3 * tp.x - tp.y) / 2.0;
                tp.x -= clamp(tp.x, -2.0, 0.0);
                sd = -length(tp) * sign(tp.y) * sz;
            } else if (int(amzp_shape) == 10) {
                float2 ap = abs(dr);
                float2 b1 = ap - float2(sz, sz * 0.3), b2 = ap - float2(sz * 0.3, sz);
                sd = min(length(max(b1, 0.0)) + min(max(b1.x, b1.y), 0.0), length(max(b2, 0.0)) + min(max(b2.x, b2.y), 0.0));
            } else if (int(amzp_shape) == 11) {
                float3 kh = float3(-0.8660254, 0.5, 0.57735027);
                float2 hx = abs(dr);
                hx -= 2.0 * min(dot(kh.xy, hx), 0.0) * kh.xy;
                hx -= float2(clamp(hx.x, -kh.z * sz * 0.9, kh.z * sz * 0.9), sz * 0.9);
                sd = length(hx) * sign(hx.y);
            } else sd = length(d) - sz * (int(amzp_shape) == 0 ? 0.35 : 1.0);
            float core = 1.0 - smoothstep(-px, px, sd);
            float halo = glowF * exp(-max(sd, 0.0) / max(sz * (int(amzp_shape) == 0 ? 0.9 : 0.6), 0.5)) * (int(amzp_shape) == 0 ? 1.0 : 0.6);
            float v = clamp(core + halo, 0.0, 1.5) * fa;
            if (v <= 0.001) continue;
            float3 col;
            if (int(amzp_colorMode) == 0) col = amzp_colA.rgb;
            else if (int(amzp_colorMode) == 1) col = mix(amzp_colA.rgb, amzp_colB.rgb, u);
            else if (int(amzp_colorMode) == 2) col = mix(amzp_colA.rgb, amzp_colB.rgb, 0.5 + 0.5 * sin(6.2831853 * (T * amzp_hueSpeed + r4)));
            else col = hue2rgb(fract(r4 + u * 0.25));
            acc.rgb += col * v * amzp_brightness * brightF;
            acc.a += min(v, 1.0);
        }
        acc.a = clamp(acc.a, 0.0, 1.0);
        acc.rgb = min(acc.rgb, float3(max(acc.a, 0.0001)) * 1.0);
        float4 bg = float4(amzp_bgCol.rgb * amzp_bgCol.a, amzp_bgCol.a);
        acc += bg * (1.0 - acc.a);
        amzOutput = nmBlend(lay, acc);
        if (!(amzp_overdrawOn>0.5)) amzOutput *= lay.a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
